/**
 * Worker bindings and the Hono app environment. Owner: Lead.
 * Runtime types (D1Database, Fetcher, ExecutionContext…) come from
 * worker-configuration.d.ts, generated by `npm run cf-typegen`.
 */

import type { SyncMessage } from './sync/queue';

export interface Bindings {
  DB: D1Database;
  ASSETS: Fetcher;
  /** The sync queue (`queues` in wrangler.jsonc): every sync runs in its consumer. See sync/queue.ts. */
  SYNC_QUEUE: Queue<SyncMessage>;
  /** Secret. 32 random bytes, base64. Encrypts provider credentials. */
  ENCRYPTION_KEY: string;
  APP_NAME: string;
  /** "true" | "false" */
  ALLOW_SIGNUP: string;
  /** Minimum minutes between automatic syncs of one connection. */
  SYNC_INTERVAL_MINUTES: string;
  /**
   * Rate Limiting bindings (`ratelimits` in wrangler.jsonc): every request, and log-in / sign-up
   * submissions, per network. Optional: without them only the D1 throttles apply.
   */
  RL_REQUESTS?: RateLimit;
  RL_AUTH?: RateLimit;
  /** Provider webhook calls, per connection (routes/webhooks.ts). Optional like the two above. */
  RL_WEBHOOKS?: RateLimit;
  /** Public Turnstile site key. With TURNSTILE_SECRET_KEY set too, log in and sign up require it. */
  TURNSTILE_SITE_KEY?: string;
  /** Secret. Turnstile secret key for Siteverify. */
  TURNSTILE_SECRET_KEY?: string;
  /**
   * Secret. Resend API key (sending access). When set, hoomuch mails sign-up confirmation links
   * and holds new accounts until their address is confirmed. Unset: no mail, no verification.
   */
  RESEND_API_KEY?: string;
  /** Sender for that mail, on a domain verified in Resend, e.g. `hoomuch <hello@example.com>`. */
  MAIL_FROM?: string;
  /**
   * "true" turns on public pages (SPEC F-21): owners can publish a product's verified revenue at
   * /p/<slug> with an embeddable badge. Anything else, the default, leaves them off.
   */
  PUBLIC_PAGES?: string;
}

export interface SessionUser {
  id: string;
  email: string;
  baseCurrency: string;
  /** IANA zone the user's days run in ('UTC' until known). See lib/time.ts and SPEC §6. */
  timeZone: string;
}

export type FlashType = 'success' | 'error' | 'info';

export interface Flash {
  type: FlashType;
  message: string;
  /**
   * An Undo for what just happened, e.g. "Add it back" after removing demo data: a button that
   * POSTs to `action` (a same-origin path). Offered instead of asking "Are you sure?" first.
   */
  undo?: { label: string; action: string };
}

export type AppEnv = {
  Bindings: Bindings;
  Variables: {
    user: SessionUser | null;
    flash: Flash | null;
    /** Throw confetti on this page (one-shot, set by sign-up). See lib/flash.ts. */
    celebrate: boolean;
    /** The signed-in account hasn't confirmed its address (false when signed out). See lib/auth.ts. */
    emailUnverified: boolean;
    /**
     * Where the display currency came from (migration 0002), read with the session so the dashboard
     * needn't ask D1 again before its own queries. 'default' when signed out.
     */
    currencySource: 'default' | 'inferred' | 'chosen';
    /** Where the time zone came from (migration 0009), after this request's inference. Like currencySource. */
    timezoneSource: 'default' | 'inferred' | 'chosen';
  };
};
